'use strict';

const fs = require('fs');
const lines = fs.readFileSync(0, 'utf8').split(/\r?\n/);
const n = parseInt(lines[0], 10);

let balance = 0;
let valid = true;

for (let i = 1; i <= n && valid; i++) {
  for (const ch of lines[i] || '') {
    if (ch === '{') balance++;
    else if (ch === '}') {
      balance--;
      if (balance < 0) {
        valid = false;
        break;
      }
    }
  }
}

console.log(valid && balance === 0 ? 'S' : 'N');
